import csv
from io import StringIO
raw='name,speed\nradar,72.0\ncamera,oops\n'
reader=csv.DictReader(StringIO(raw))
if 'speed' not in (reader.fieldnames or []):
    raise ValueError('缺少speed列')
for row in reader:
    try:
        print(float(row['speed']))
    except ValueError:
        print('第',reader.line_num,'行速度不是数字')

import json
bad='{"valid": True}'
try:
    json.loads(bad)
except json.JSONDecodeError:
    print('JSON语法不合法')
obj=json.loads('{"status":"ACTIVE"}')
try:
    print(obj['valid'])
except KeyError:
    print('缺少valid字段')
